{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap (2026 maximum)","requirement":"A landlord may charge a screening fee only if a unit is available, may not exceed the state cap, must give the applicant a receipt and an itemized cost list, refund any unused portion, and return the fee to applicants not selected.","key_value":"$68.96 for 2026","coverage_conditions":"Prospective tenants of residential rental units; fee allowed only when a unit is actually available; landlord must use a tenant-provided reusable screening report.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental units; statewide."},"exemptions":null,"penalty":null,"effective_date":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California reusable screening report requirement","requirement":"If a tenant provides a reusable screening report, the landlord must use it instead of screening the applicant again.","key_value":null,"coverage_conditions":"Prospective tenants of residential rental units statewide who provide a reusable screening report.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental units; statewide."},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"If the tenant provides a reusable screening report, the landlord must use it.","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley screening fee disclosure and renewal application fee limits","requirement":"An owner who charges a screening fee must give applicants a clear tenant screening fee rights statement and the maximum fee cap under California Civil Code § 1950.6(b), and may not charge existing tenants a non-refundable fee to renew a tenancy.","key_value":null,"coverage_conditions":"All residential rental agreements in Berkeley, regardless of contrary lease language; applies to owners and their agents who charge screening fees or fees to existing tenants.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All residential rental agreements in Berkeley."},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates this chapter is unenforceable.","effective_date":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":"Requires disclosure of the maximum screening fee cap permitted under California Civil Code § 1950.6(b).","confidence":0.8,"conflict_flag":false,"conflict_note":null}
